import runtime as rt
import pipeline as pp
import json,numpy as np,html,time

def main():
 R=['# 多视角二维轮廓升维 → 固定细三维轮廓线\n', '**结论：PARTIAL_THIN_FIXED_CURVES；NO_GO_COMPLETE_CONTOUR。** 两场景均交付真正固定的1D控制图和细实体管线，并执行跨视角控制点融合与重复edge消除；不再是椭球支撑填面。但Lego形体大量缺线，Chair也有断口、重线和后方线；没有完成可靠、较完整且连续的固定三维轮廓恢复。\n', '入口：[离线交付索引](INDEX.html) · [方法设计](METHOD_DESIGN_ZH.md) · [事前协议](PROTOCOL.json) · [融合冻结](FUSION_FREEZE.json) · [复现](REPRODUCE.md) · [执行边界与已知缺陷](EXECUTION_NOTES_ZH.md)。\n', '本轮从二维有序alpha边界沿校准射线升维，不使用旧面域网格、不缩小或改名旧面、不作ellipsoid/voxel union、closing、全物体黑剪影、GTmesh/depth/scan输入、训练或安装。主GLB/OBJ是新生成的世界坐标三角管线；centerline OBJ/PLY/JSON是固定1D控制点与连接。XYZ、拓扑、radius及path IDs封印后，所有相机只投影它们。\n', '所有媒体均为**资产自身z-buffer、相对原GS的x-ray**。原物体表面独立遮挡没有校准，因此后方线完整保留；未用深度proxy、前景mask、逐帧重选或二维修正隐藏错误。\n']
 summaries={}
 for n in ('lego','chair'):
  s=pp.scene(n);asset=json.loads((rt.ART/'results'/(n+'_asset.json')).read_text());fusion=json.loads((rt.ART/'results'/(n+'_fusion.json')).read_text());audit=json.loads((rt.ART/'results'/(n+'_contract_audit.json')).read_text());supp=json.loads((rt.ART/'results'/(n+'_supplement.json')).read_text());width=json.loads((rt.ART/'results'/(n+'_WIDTH_PROFILES.json')).read_text())['rows'];video=json.loads((rt.ART/'media'/n/'arc/three_arms_33.manifest.json').read_text());metrics={}
  for arm in ('single','rawunion','fused'):
   vals=[json.loads((rt.ART/'results'/f'{n}_reserved_{k}.json').read_text())['metrics'][arm] for k in s['roles']['reserved']];metrics[arm]={k:float(np.mean([m[k] for m in vals])) for k in ('coverage3','ink_over_foreground','foreground_blank_fraction','negative_space_fill_fraction','hole_fill_fraction','artifact_diameter_p95_px','largest_dense_core_component','longest_gap_px','background_far_fraction','deep_interior_fraction')};metrics[arm]['analytic_diameter_p95_max']=max(m['analytic_diameter_quantiles'][2] for m in vals)
  rows=[r for r in width if r['arm']=='fused'];widthvals=[x['diameter_px'] for r in rows for x in r['records']];worst=max([r for r in rows if r['isolated_profiles']],key=lambda r:r['diameter_p50_p95_p99_max'][1]);edge=audit['edge'];track=audit['source_track']
  summaries[n]=dict(verdict='PARTIAL_THIN_FIXED_CURVES / NO_GO_COMPLETE_CONTOUR',asset=asset['arms'],world_radius=asset['world_radius'],metrics=metrics,fusion=fusion,edge_audit=edge,source_track=track,profile_count=len(widthvals),profile_quantiles=np.quantile(widthvals,[.5,.95,.99,1]).tolist(),worst_profile_camera=worst['camera'],worst_profile_count=worst['isolated_profiles'],worst_profile_p95=worst['diameter_p50_p95_p99_max'][1],video_decode_frames=video['decoded_frames'])
  R+=['## '+n.capitalize()+'\n',f'[推荐 fused GLB](assets/{n}/fused/tubes.glb) · [实体tube OBJ](assets/{n}/fused/tubes.obj) · [中心线OBJ](assets/{n}/fused/centerlines.obj) · [带24单source切换的离线3D查看器](assets/{n}/viewer_with_sources.html)\n', f'[8 reserved完整800px板](media/{n}/reserved_eight_FULL.png) · [轻量预览](media/{n}/reserved_eight_preview.jpg) · [三臂完整33相机视频](media/{n}/arc/three_arms_33.mp4) · [全部33帧](media/{n}/arc/ALL_33_FRAMES.jpg) · [宽尾原样与单管隔离检查](media/{n}/WIDTH_TAILS.png)\n']
  if n=='lego':R+=['实际观察：底板外周和铲斗较稳定边界被恢复成细线；rawunion能看出更多车身与支架，但重线/杂线多。fused大量删去车身、驾驶室和抬升支架的片段，只靠底板与铲斗不能称完整Lego轮廓。源proxy偏移、保守多源筛选以及局部连接不足同时造成缺线；没有独立因果消融把缺陷唯一归于某一项。\n']
  else:R+=['实际观察：椅背、座面周界、部分扶手与腿部可读，较rawunion清楚；但断口、双线和后方座椅结构穿出仍很明显。从后方看前侧曲线仍显示，这是未处理原物体遮挡的真实xray，不以此冒充物理可见轮廓。\n']
  R+=['下表为8reserved逐视角均值；coverage3相对独立alpha边界，非GTmesh精度。墨量/前景包含背景墨；前景空白只在前景内计算。封闭孔与convex-hull内开放/封闭负空间分别测量。\n','|固定臂|轮廓覆盖3px|墨量/前景|前景空白|负空间填充|封闭孔填充|全墨迹EDT直径p95|最长缺口px|\n|---|---:|---:|---:|---:|---:|---:|---:|']
  for arm,m in metrics.items():R+=[f"|{arm}|{m['coverage3']:.1%}|{m['ink_over_foreground']:.1%}|{m['foreground_blank_fraction']:.1%}|{m['negative_space_fill_fraction']:.1%}|{m['hole_fill_fraction']:.1%}|{m['artifact_diameter_p95_px']:.2f}|{m['longest_gap_px']:.1f}|"]
  R+=['',f"三个臂世界radius完全相同：**{asset['world_radius']:.9f}**，参考直径约2px；reserved中fused解析投影直径p95最大为{metrics['fused']['analytic_diameter_p95_max']:.3f}px。选择只用了4DEV相机的几何投影，甚至没有用DEV图像挑宽；图像评价在资产seal后才打开。有限候选是0.75/1/1.25倍construction中位世界像素尺度。\n",f"实际full-mask候选孤立profile：fused共{len(widthvals)}条，合并样本p95={np.quantile(widthvals,.95):.3f}px；最差单视角{worst['camera']}只有{worst['isolated_profiles']}条，p95={worst['diameter_p50_p95_p99_max'][1]:.3f}px。该筛法只排除9×9窗口中的其他获胜path，**同一path非局部折返/重叠仍可能残留**，所以不是严格独立stroke保证，最差视角超过6px。WIDTH_TAILS把各臂最差4例保留，并将同一根真实管线单独raster验证：单管薄不能否认合图局部变宽。全墨迹EDT、密集墨核等指标独立保留，不以半径平均值救成GO。\n",f"全墨迹中内接半径>3px的最大连续密集核面积，rawunion/fused的视角均值为{metrics['rawunion']['largest_dense_core_component']:.1f}/{metrics['fused']['largest_dense_core_component']:.1f}像素；rawunion的大片交叉墨明显减少，但没有完全消失。这个量不等于整块连通墨迹面积。\n"]
  R+=['|图结构|源点/融合点|edges|按分叉切分路径数|≤3点短路径数|近重复诊断对|\n|---|---:|---:|---:|---:|---:|']
  for arm,a in asset['arms'].items():R+=[f"|{arm}|{a['nodes']}|{a['edges']}|{a['paths']}|{a['short_paths']}|{supp['duplicate_counts'][arm]}|"]
  R+=['',f"确有跨视角融合：{fusion['cluster_merges']:,}次受约束节点簇合并，消除{fusion['duplicate_edges_removed']:,}条重复edge；拒绝{fusion['rejected_raw_edges']:,}条raw edge进入fused。近重复诊断是中点≤0.5wpp、反向等价切向dot≥.96、不共端点、12近邻内的保守计数，不是严格重复几何总数。大量短path也受分叉处切段定义影响，不等于同数量物体部件，但清楚显示连续性代价。\n",f"保留的限制有量化证据：{edge['source_camera_histogram'].get('1',0):,}/{asset['arms']['fused']['edges']:,}条fused edge仅有一个直接source camera，尽管两端各至少两个来源。相对各原source edge的方向翻转实例{edge['raw_source_direction_reversals']}，最终超过初始6wpp边长阈值的edge有{edge['over_initial_6wpp_limit']}条；长度p95/max={edge['final_length_wpp_quantiles'][1]:.3f}/{edge['final_length_wpp_quantiles'][3]:.3f}wpp。没有新增跨链桥，但端点融合不保证方向与边长不变。\n",f"全部最终source端点重投影最大{track['max_reprojection_px']:.6f}px、位移最大{track['max_displacement_wpp']:.6f}wpp，确实满足冻结节点界限。然而anchor窗口规则出现{track['local_direction_sign_changes']}次局部方向符号变化、{track['accepted_pairs_with_fewer_than3_final_local_votes']}个最终不足3票的accepted pair；不能把它称为严格单调轨迹或已证实物理同一性。详见[逐边审计](results/{n}_EDGE_AUDIT.json)及[完整契约审计](results/{n}_contract_audit.json)。\n",f"外/孔边界均提取，周长<16px的小环在24construction累计排除{supp['small_contours_excluded']}个；数量是每视角计数，不是不同物体孔数量。全部被拒绝/未融合源线仍在rawunion和24份sources资产，不因reserved结果裁剪。\n",'前四个预定reserved关键视角均保存800×800原RGB、独立2D参考、三臂tube、overlay及确定性edgezoom：\n']
  R+=[' · '.join(f'[{k}全图](media/{n}/reserved/{k}/FULL.png) / [fused800](media/{n}/reserved/{k}/fused.png) / [edgezoom](media/{n}/reserved/{k}/edgezoom.png)' for k in s['roles']['reserved'][:4])+'\n']
  R+=[f"construction：{', '.join(s['roles']['construction'])}。DEV：{', '.join(s['roles']['dev'])}。reserved：{', '.join(s['roles']['reserved'])}。86metadata相机到最近construction方向的最大夹角{ s['coverage']['max_nearest_construct_deg']:.2f}°。\n"]
 R+=['## 方法和证据应如何解释\n','单源为本轮重新生成的r_33，与rawunion/fused共用all-accepted条件中位中心z proxy、2px有序采样、孔边界、跳变切段、radius和实体renderer。旧r_33用top32 αT×C_style中心均值，不能把本轮结果冒称旧实现纯增source。single→rawunion增加source；rawunion→fused同时改变同一性筛选、控制点融合、重复边合并和pruning，收益不能唯一归给去重。\n','每像素完整accepted核ID/αT由新stage稀疏CPU接口得到；条件median沿相机射线升维。q10/q90是支持核中心深度分布，**不是测量surface depth或校准误差区间**。没有统一depth平面，也没有将不同相机的pseudo-depth当物理真值。三角化只用于通过近距、支撑、双向epipolar、切向和夹角检查的候选；共享核与低重投影误差仍不足以证明rolling silhouette的物理同一性。\n','本轮source回投影数值近零是构造自检；最终多source≤2px是真实几何约束，但不能证明深度正确或完整轮廓。没有实现内部RGB细节层，没有mesh GT评测；不作方法新颖性声明。旧NO_GO_CONTOUR_OVERFILL、旧单源/稀疏图/容量证书均保持原状态。\n','所有86metadata相机都来自原GS训练/历史研究曝光域。24construction/4DEV/8reserved及33arc完整继承上轮，按真实file_path核对，不按r数字index（r_33实际index28）。reserved仅本轮构线holdout，**不是fresh blind、GS-unseen**。33arc是历史较短弧段，完整视频不代表全方向泛化；下半球和相机域外完整性未验证。\n','## 工程核验和可复现边界\n','原模型每scene按冻结SHA核验；48construction缓存逐相机seal/result/input/hash绑定，稀疏accepted和逐采样像素对sealed alpha核对。CPU full-forward CPP与历史已校准源码逐字相同；历史四份native-cache对照仅近似，不宣称CUDA bit-exact，也没有本轮执行CUDA。详见[CPU校准链](CPU_CALIBRATION_LINEAGE.json)。\n','8项初始tracer真实RED→GREEN发生在批处理前；新增7项实际production路径扩展在asset后、评价前通过；最终10项扩展加入rolling distinct-support拒绝、近平行拒绝及反向轨迹，并在评价后通过。日志和时序完整保留。它们不等于所有更强几何目标已通过；严格monotonic/边方向连续/完整性没有GREEN认证。\n','全部54个导出图（每scene3主臂+24source）的GLB/实体OBJ/控制点PLY/JSON/路径边逐项读回；真实管径检查通过。独立审计检查每个来源端点界限、edge provenance、所有source→fusion→asset依赖与预冻结代码hash。原导出单source edge IDs与主raw edge IDs命名空间不同，由各scene [PROVENANCE_NAMESPACES](assets/lego/PROVENANCE_NAMESPACES.json) sidecar明确映射，未覆盖旧sealed字节。\n','两段H264 yuv420p +faststart视频均完整decode33/33，全部帧和camera/geometry hash保存；前后asset seal相同。离线WebGL2查看器内嵌27份实际几何，静态数组及node语法核验通过；环境未进行浏览器交互验收，不能声称实际拖动测试通过。\n','所有生产顺序执行、CPU-only、2线程，cache/tmp/private binary仅新stage；没有等待或干扰GPU、其他进程/工作树。资源及原模型/1130保护文件/旧branch核验见[PROTECTION_AUDIT](PROTECTION_AUDIT.json)。最终提交、显式SSH push、remote SHA读回及clean状态在ignored `out/gaer_multiview_contour_lift_v01/DELIVERY.json`，不把自身commit SHA写回tracked报告形成循环。\n','此次最早被结果否定的主张不是“多视角升维完全无用”，而是当前严格有限proxy与局部匹配足以产出完整且连续的固定轮廓。它确实产生了薄、可编辑、可追溯的多源融合候选，也减少了重复墨迹；但覆盖、连续性、局部顺序和物理遮挡仍不足。保持PARTIAL/NO_GO，不用线宽救失败。\n']
 rt.scoped(rt.ART/'REPORT_ZH.md').write_text('\n'.join(R).replace('没有新增跨链桥，但端点融合不保证方向与边长不变。','每条edge都映射原chain邻接，未显式新增跨链edge；但簇合并会改变连通关系，不能推出负空间绝不会跨接，也不保证方向与边长不变。'))
 rt.atomic_json(rt.ART/'RESULT_SUMMARY.json',dict(scenes=summaries,generated_utc=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())))
 page=['<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>固定细三维轮廓线</title><style>body{font:17px system-ui;max-width:1500px;margin:30px auto;padding:0 24px;color:#20252b}a{color:#165daf}section{margin:36px 0;border-top:1px solid #ccd;padding-top:24px}.images{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.images img{width:100%}small{color:#555}video{width:100%}.status{padding:18px;background:#fff2d9}figure{margin:0}</style><h1>多视角二维轮廓升维 → 固定细3D线</h1><p class="status"><b>PARTIAL / NO_GO 完整轮廓恢复。</b> 两个真实固定线模型；多源融合与去重已执行。仍有断线、缺线、重叠和后方线，绝不以退出成功代替视觉GO。</p><p>XYZ、拓扑和世界线宽已冻结。三臂共用radius；实体tube自身z-buffer，相对原GS为x-ray。</p><p><a href="REPORT_ZH.md">中文报告</a> · <a href="REPRODUCE.md">复现</a> · <a href="RESULT_SUMMARY.json">实测JSON</a></p>']
 for n in ('lego','chair'):
  page.append(f'<section><h2>{n.capitalize()}</h2><p><a href="assets/{n}/viewer_with_sources.html">离线3D旋转查看器（默认fused，可切24source）</a> · <a href="assets/{n}/fused/tubes.glb">fused GLB</a> · <a href="assets/{n}/fused/tubes.obj">tube OBJ</a> · <a href="assets/{n}/fused/centerlines.obj">centerline OBJ</a> · <a href="assets/{n}/fused/CENTERLINES.json">控制点/路径/来源</a></p><div class="images">')
  for label,key in [('原SH3','original'),('独立2D参考（非最终墨迹）','reference2D'),('完整rawunion实体线','rawunion'),('fused候选实体线','fused')]:page.append(f'<figure><img src="media/{n}/reserved/r_14/{key}.png"><figcaption>{label} · r_14</figcaption></figure>')
  page.append(f'</div><p><a href="media/{n}/reserved_eight_FULL.png">8reserved完整全图板</a> · <a href="media/{n}/reserved_eight_preview.jpg">预览</a> · <a href="media/{n}/WIDTH_TAILS.png">最差宽尾/单管隔离</a> · <a href="media/{n}/arc/ALL_33_FRAMES.jpg">全部33帧</a></p><video controls preload="metadata" src="media/{n}/arc/three_arms_33.mp4"></video><p><small>历史曝光的33相机短弧；无删帧、无几何更新。所有孔洞/遮挡/重叠失败保留。</small></p></section>')
 page.append('</html>');(rt.ART/'INDEX.html').write_text('\n'.join(page))
 print('REPORT_WRITTEN',flush=True)
if __name__=='__main__':main()
